"""Install the checked browser simulator and additive app-builder backend."""

import argparse
import base64
import gzip
import json
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = ''  # noqa: E501 - reviewed source bundle


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = Path(tempfile.mkdtemp(prefix="dhanz-app-simulator-", dir=Path.home()))
    root.chmod(0o700)
    files = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    for name, source in files.items():
        (root / name).write_text(source)
        (root / name).chmod(0o600)
    sys.path.insert(0, str(root))
    from web_release import fetch_release, version_key

    release = fetch_release()
    if version_key(release["version"], release["build"]) < version_key("0.10.4", 41):
        raise ValueError("The checked simulator browser build is not published yet. Nothing changed.")
    # Validate/stage the actual Caddy browser mount and package before restarting API.
    sys.argv = [str(root / "apply_web_release.py")]
    runpy.run_path(sys.argv[0], run_name="__main__")
    sys.argv = [str(root / "install_app_builder_chat.py")] + (["--apply"] if args.apply else [])
    runpy.run_path(sys.argv[0], run_name="__main__")
    if args.apply:
        sys.argv = [str(root / "apply_web_release.py"), "--apply"]
        runpy.run_path(sys.argv[0], run_name="__main__")
        print("App simulator installed. Refresh Edge with Ctrl+F5; close and reopen the Android web app.")
        print(
            "Press App simulator above chat, or Open simulator on a build card. Use Update app & simulator for changes."
        )
        print("Browser companion only, not an Android emulator. Revisions use your configured AI API credits.")


if __name__ == "__main__":
    os.umask(0o077)
    try:
        main()
    except (ValueError, OSError) as exc:
        raise SystemExit(str(exc)) from None
